rc=0; if [ -f /etc/morpheus/ssl/m_cust_test.crt ] && [ ! -L /etc/morpheus/ssl/m_cust_test.crt ]; then rm -f -- /etc/morpheus/ssl/m_cust_test.crt && echo 'removed /etc/morpheus/ssl/m_cust_test.crt' || rc=1; fi; if [ -f /etc/morpheus/ssl/m_cust_test.key ] && [ ! -L /etc/morpheus/ssl/m_cust_test.key ]; then shred -u /etc/morpheus/ssl/m_cust_test.key && echo 'shredded /etc/morpheus/ssl/m_cust_test.key' || rc=1; fi; exit $rc
